DROP TABLE IF EXISTS public.schedule_class_rooms CASCADE;
DROP TABLE IF EXISTS public.activity_class_rooms CASCADE;
DROP TABLE IF EXISTS public.activities CASCADE;
DROP TABLE IF EXISTS public.activity_schedules CASCADE;
DROP TABLE IF EXISTS public.class_rooms CASCADE;
DROP TABLE IF EXISTS public.implementation_bases CASCADE;
DROP TABLE IF EXISTS public.report_categories CASCADE;
DROP TABLE IF EXISTS public.profiles CASCADE;
DROP TABLE IF EXISTS public.schools CASCADE;
DROP TABLE IF EXISTS public.school_settings CASCADE;
DROP TABLE IF EXISTS public.users CASCADE;

-- 1. Membuat tabel public.users (pengganti auth.users untuk local auth)
CREATE TABLE public.users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Membuat tabel public.schools
CREATE TABLE public.schools (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    address TEXT,
    headmaster_name TEXT,
    headmaster_nip TEXT,
    logo_url TEXT,
    invite_code TEXT DEFAULT substr(md5((random())::text), 1, 8),
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    headmaster_pangkat TEXT,
    headmaster_jabatan TEXT,
    npsn VARCHAR(50),
    city TEXT
);

-- 3. Membuat tabel public.profiles (referensi ke public.users dan public.schools)
CREATE TABLE public.profiles (
    id UUID PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,
    nip TEXT,
    name TEXT,
    pangkat_gol TEXT,
    jabatan TEXT,
    unit_kerja TEXT,
    subject TEXT,
    role TEXT DEFAULT 'user',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    avatar_url TEXT,
    report_notifications BOOLEAN DEFAULT TRUE,
    theme TEXT DEFAULT 'light',
    school_id UUID REFERENCES public.schools(id) ON DELETE SET NULL
);

-- 4. Membuat tabel public.report_categories
CREATE TABLE public.report_categories (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    rhk_label TEXT NOT NULL,
    is_teaching BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    school_id UUID REFERENCES public.schools(id) ON DELETE SET NULL
);

-- 5. Membuat tabel public.implementation_bases
CREATE TABLE public.implementation_bases (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    school_id UUID REFERENCES public.schools(id) ON DELETE SET NULL
);

-- 6. Membuat tabel public.class_rooms
CREATE TABLE public.class_rooms (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    user_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    school_id UUID REFERENCES public.schools(id) ON DELETE SET NULL
);

-- 7. Membuat tabel public.activity_schedules
CREATE TABLE public.activity_schedules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE,
    school_id UUID REFERENCES public.schools(id) ON DELETE CASCADE,
    category_id BIGINT REFERENCES public.report_categories(id) ON DELETE SET NULL,
    implementation_basis_id BIGINT REFERENCES public.implementation_bases(id) ON DELETE SET NULL,
    day_of_week INTEGER NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
    topic TEXT,
    description TEXT,
    student_outcome TEXT,
    teaching_hours INTEGER,
    student_count INTEGER,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 8. Membuat tabel public.activities
CREATE TABLE public.activities (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    category_id BIGINT NOT NULL REFERENCES public.report_categories(id) ON DELETE RESTRICT,
    activity_date DATE NOT NULL DEFAULT CURRENT_DATE,
    implementation_basis_id BIGINT REFERENCES public.implementation_bases(id) ON DELETE SET NULL,
    description TEXT NOT NULL,
    output_result TEXT,
    evidence_link TEXT,
    period_start INTEGER,
    period_end INTEGER,
    topic TEXT,
    student_outcome TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    teaching_hours TEXT,
    learning_material TEXT,
    learning_outcome TEXT,
    status TEXT DEFAULT 'Selesai',
    student_count INTEGER,
    school_id UUID REFERENCES public.schools(id) ON DELETE SET NULL,
    schedule_id UUID REFERENCES public.activity_schedules(id) ON DELETE SET NULL
);

-- 9. Membuat tabel public.activity_class_rooms
CREATE TABLE public.activity_class_rooms (
    activity_id BIGINT REFERENCES public.activities(id) ON DELETE CASCADE,
    class_room_id BIGINT REFERENCES public.class_rooms(id) ON DELETE CASCADE,
    PRIMARY KEY (activity_id, class_room_id)
);

-- 10. Membuat tabel public.schedule_class_rooms
CREATE TABLE public.schedule_class_rooms (
    id SERIAL PRIMARY KEY,
    schedule_id UUID REFERENCES public.activity_schedules(id) ON DELETE CASCADE,
    class_room_id BIGINT REFERENCES public.class_rooms(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 11. Membuat tabel public.school_settings
CREATE TABLE public.school_settings (
    id BIGSERIAL PRIMARY KEY,
    school_name TEXT NOT NULL,
    school_address TEXT,
    headmaster_name TEXT,
    headmaster_nip TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    headmaster_pangkat TEXT,
    headmaster_jabatan TEXT DEFAULT 'Kepala Madrasah'
);

